def gif_encode_frames(frames, delays, filename, loop=0):
    # frames: list of (w,h, pixels) where pixels is a flat bytearray of RGB
    # Build global color table? We'll use per-frame LCT.
    out = bytearray()
    out += b"GIF89a"
    # Logical Screen Descriptor
    w = max(f[0] for f in frames); h = max(f[1] for f in frames)
    packed = 0x00  # no global color table
    out += struct.pack("<HHBBB", w, h, packed, 0, 0)
    # Application extension for loop
    if loop:
