def build_palette(pixels):
    order = []
    seen = {}
    for i in range(0, len(pixels), 3):
        c = (pixels[i], pixels[i+1], pixels[i+2])
        if c not in seen:
            seen[c] = len(order)
            order.append(c)
    if len(order) > 256:
        raise ValueError("frame uses %d colors (>256)" % len(order))
    size = 2
    while size < len(order):
        size <<= 1
    nbits = int(math.log2(size))
    pal_index = {c: i for i, c in enumerate(order)}
    indices = [pal_index[(pixels[i], pixels[i+1], pixels[i+2])] for i in range(0, len(pixels), 3)]
    return order, size, nbits, indices

