package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"image"
	"image/color"
	"image/gif"
	"os"
	"sort"
)

// Frame describes one raw RGB frame to encode.
type Frame struct {
	File  string  `json:"file"`
	W     int     `json:"w"`
	H     int     `json:"h"`
	Delay float64 `json:"delay"`
}

// Spec is the manifest for a single output GIF.
type Spec struct {
	Out    string  `json:"out"`
	Frames []Frame `json:"frames"`
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: giftool <spec.json>")
		os.Exit(2)
	}
	specData, err := os.ReadFile(os.Args[1])
	if err != nil {
		fatal(err)
	}
	var spec Spec
	if err := json.Unmarshal(specData, &spec); err != nil {
		fatal(err)
	}

	var g gif.GIF
	g.LoopCount = 0
	g.Config.Width = spec.Frames[0].W
	g.Config.Height = spec.Frames[0].H

	for _, fr := range spec.Frames {
		raw, err := os.ReadFile(fr.File)
		if err != nil {
			fatal(err)
		}
		if len(raw) != fr.W*fr.H*3 {
			fatal(fmt.Errorf("%s: expected %d bytes got %d", fr.File, fr.W*fr.H*3, len(raw)))
		}
		pal, idx := buildPalette(raw)
		pimg := image.NewPaletted(image.Rect(0, 0, fr.W, fr.H), pal)
		for i, ix := range idx {
			pimg.Pix[i] = uint8(ix)
		}
		g.Image = append(g.Image, pimg)
		g.Delay = append(g.Delay, int(fr.Delay*100))
	}

	out, err := os.Create(spec.Out)
	if err != nil {
		fatal(err)
	}
	w := bufio.NewWriter(out)
	if err := gif.EncodeAll(w, &g); err != nil {
		fatal(err)
	}
	if err := w.Flush(); err != nil {
		fatal(err)
	}
	if err := out.Close(); err != nil {
		fatal(err)
	}
	fmt.Println("wrote", spec.Out)
}

func buildPalette(raw []byte) (color.Palette, []int) {
	seen := make(map[[3]byte]int)
	var order [][3]byte
	for i := 0; i < len(raw); i += 3 {
		t := [3]byte{raw[i], raw[i+1], raw[i+2]}
		if _, ok := seen[t]; !ok {
			seen[t] = len(order)
			order = append(order, t)
		}
	}
	if len(order) > 256 {
		fatal(fmt.Errorf("frame uses %d colors (>256)", len(order)))
	}
	sort.Slice(order, func(a, b int) bool {
		ka := order[a]
		kb := order[b]
		if ka[0] != kb[0] {
			return ka[0] < kb[0]
		}
		if ka[1] != kb[1] {
			return ka[1] < kb[1]
		}
		return ka[2] < kb[2]
	})
	pal := make(color.Palette, len(order))
	for i, t := range order {
		pal[i] = color.RGBA{t[0], t[1], t[2], 255}
	}
	idx := make([]int, len(raw)/3)
	m := make(map[[3]byte]int, len(order))
	for i, t := range order {
		m[t] = i
	}
	for i := 0; i < len(raw); i += 3 {
		idx[i/3] = m[[3]byte{raw[i], raw[i+1], raw[i+2]}]
	}
	return pal, idx
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "giftool:", err)
	os.Exit(1)
}
EOF
