import sys, zlib, struct, os

def read_png(path):
    d = open(path, "rb").read()
    pos = 8; idat = b""
    while pos < len(d):
        ln = struct.unpack(">I", d[pos:pos+4])[0]
        tag = d[pos+4:pos+8]
        chunk = d[pos+8:pos+8+ln]
        if tag == b"IHDR":
            w, h, bd, ct = struct.unpack(">IIBB", chunk[:10])
        elif tag == b"IDAT":
            idat += chunk
        pos += 12 + ln
    raw = zlib.decompress(idat)
    return w, h, raw

def ascii_preview(path, cols=100, rows=28):
    w, h, raw = read_png(path)
    stride = w*3+1
    out = []
    for r in range(rows):
        line = []
        yy = int((r+0.5) * h / rows)
        for c in range(cols):
            xx = int((c+0.5) * w / cols)
            off = yy*stride + 1 + xx*3
            r_, g_, b_ = raw[off], raw[off+1], raw[off+2]
            lum = 0.299*r_ + 0.587*g_ + 0.114*b_
            # detect non-neutral (colored) pixels
            mx, mn = max(r_,g_,b_), min(r_,g_,b_)
            if mx - mn > 40:
                ch = "#"
            elif lum > 240:
                ch = " "
            elif lum > 200:
                ch = "."
            elif lum > 150:
                ch = "+"
            elif lum > 100:
                ch = "o"
            elif lum > 50:
                ch = "O"
            else:
                ch = "@"
            line.append(ch)
        out.append("".join(line))
    return "\n".join(out)

for f in sorted(os.listdir("/tmp/opencode/genout")):
    if f.endswith(".png"):
        print("="*100)
        print(f)
        print(ascii_preview(os.path.join("/tmp/opencode/genout", f)))
EOF

